            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            r0 = min(y for y, x in component)
            r1 = max(y for y, x in component)
            c0 = min(x for y, x in component)
            c1 = max(x for y, x in component)
            gaps = [x for x in range(c0, c1 + 1) if grid[r0][x] == 0]
            if len(gaps) != 1:
                continue
            gap = gaps[0]
            for y in range(r0, r1 + 1):
                for x in range(c0, c1 + 1):
                    if grid[y][x] == 0:
                        out[y][x] = 2
            if r0 > 0:
                if gap - c0 > c1 - gap:
                    for x in range(gap + 1):
                        out[r0 - 1][x] = 2
                else:
                    for x in range(gap, w):
